48	    enable_mmap_ = enable_mmap;
49	  }
50	
51	  bool enable_mmap() const {
52	    return enable_mmap_;
53	  }
54	
55	  Status add_persisted_segment_meta(const SegmentMeta::Ptr &meta) {
56	    if (meta == nullptr) {
57	      return Status::InvalidArgument("Segment meta is null");
58	    }
59	    auto iter = persisted_segment_metas_map_.find(meta->id());
60	    if (iter != persisted_segment_metas_map_.end()) {
61	      return Status::InvalidArgument("Segment meta already exists");
62	    }
63	    persisted_segment_metas_map_[meta->id()] = meta;
64	    return Status::OK();
65	  }
66	
67	  Status remove_persisted_segment_meta(SegmentID segment_id) {
68	    auto iter = persisted_segment_metas_map_.find(segment_id);
69	    if (iter == persisted_segment_metas_map_.end()) {
70	      return Status::NotFound("Segment meta not found");
71	    }
72	    persisted_segment_metas_map_.erase(segment_id);
73	    return Status::OK();
74	  }
75	
76	  Status update_persisted_segment_meta(SegmentMeta::Ptr meta) {
77	    if (meta == nullptr) {
78	      return Status::InvalidArgument("Segment meta is null");
79	    }
80	    auto iter = persisted_segment_metas_map_.find(meta->id());
81	    if (iter == persisted_segment_metas_map_.end()) {
82	      return Status::NotFound("Segment meta not found");
83	    }
84	    persisted_segment_metas_map_[meta->id()] =
85	        std::make_shared<SegmentMeta>(*meta);
86	    return Status::OK();
87	  }
88	
89	  void set_persisted_segment_metas(const std::vector<SegmentMeta::Ptr> &metas) {
90	    for (auto &meta : metas) {
91	      persisted_segment_metas_map_[meta->id()] = meta;
92	    }
93	  }
94	
95	  std::vector<SegmentMeta::Ptr> persisted_segment_metas() const {
96	    std::vector<SegmentMeta::Ptr> segment_metas;
97	    segment_metas.reserve(persisted_segment_metas_map_.size());
98	    for (auto &segment_meta : persisted_segment_metas_map_) {
99	      segment_metas.push_back(segment_meta.second);
100	    }
101	
102	    std::sort(segment_metas.begin(), segment_metas.end(),
103	              [](const SegmentMeta::Ptr &lhs, const SegmentMeta::Ptr &rhs) {
104	                return lhs->min_doc_id() < rhs->min_doc_id();
105	              });
106	
107	    return segment_metas;
108	  }
