131	    return delete_snapshot_path_suffix_;
132	  }
133	
134	  void set_next_segment_id(SegmentID id) {
135	    next_segment_id_ = id;
136	  }
137	
138	  SegmentID next_segment_id() const {
139	    return next_segment_id_;
140	  }
141	
142	 public:
143	  bool operator==(const Version &other) const {
144	    if (*schema_ != *other.schema_ ||
145	        persisted_segment_metas_map_.size() !=
146	            other.persisted_segment_metas_map_.size()) {
147	      return false;
148	    }
149	
150	    for (const auto &item : persisted_segment_metas_map_) {
151	      auto it = other.persisted_segment_metas_map_.find(item.first);
152	      if (it == other.persisted_segment_metas_map_.end() ||
153	          *item.second != *it->second) {
154	        return false;
155	      }
156	    }
157	
158	    return true;
159	  }
160	
161	  std::string to_string() const;
162	
163	  std::string to_string_formatted(int indent_level = 0) const;
164	
165	 private:
166	  CollectionSchema::Ptr schema_;
167	  bool enable_mmap_{false};
168	
169	  std::unordered_map<SegmentID, SegmentMeta::Ptr> persisted_segment_metas_map_;
170	
171	  SegmentMeta::Ptr writing_segment_meta_;
172	
173	  uint32_t id_map_path_suffix_{0};
174	  uint32_t delete_snapshot_path_suffix_{0};
175	
176	  SegmentID next_segment_id_{0};
